import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.BXzK3EA4.js";const i="/assets/861db5454e637cf5.BpB55mm2.png",d="/assets/0712cc9777d17156.i4KJBbLq.png",r="/assets/d0cb01335ede0236.hc-ETXAs.png",p="/assets/efc4cc901f0e1d63.Duf7NRbo.png",o="/assets/ce43dddb41af5cca.odAjd8QW.png",n="/assets/fa5c31cbba7f8079.YWzNVUW3.png",c="/assets/3119ee99548c5ac7.DaTQNc4u.png",b="/assets/83666dd29bb88747.C1pwWxoz.png",h="/assets/6a31e1c005a9452f.DYuH8KJ5.png",f="/assets/07c2b69aa594d0d9.D5ncjEXz.png",u="/assets/b436d92f95ba9e51.B0nzPfm-.png",m="/assets/42dfe263f25bbe54.CTLK1XFK.png",g="/assets/cef53288604fdb11.hWADJfJu.png",v="/assets/d447b5fee231cc28.BA5EZlX4.png",k="/assets/d4852966170674ea.DwTQ7GyV.png",B=JSON.parse('{"title":"linux系统硬盘的挂载与扩容","description":"","frontmatter":{"title":"linux系统硬盘的挂载与扩容"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/disk-mount-and-expand.md","filePath":"ops-knowledge-base/operating-system/linux/disk-mount-and-expand.md","lastUpdated":1788259091000}'),_={name:"ops-knowledge-base/operating-system/linux/disk-mount-and-expand.md"};function x(q,a,w,P,y,D){return s(),t("div",null,[...a[0]||(a[0]=[l('<p>针对使用机器后期添加硬盘需手动挂载与扩容操作</p><p>数据无价,操作格式化之前确定数据已备份</p><p><strong>一、新分区挂载</strong></p><ul><li>#lsblk #查看当前系统识别的硬盘，记住新硬盘名称</li></ul><p><img src="'+i+'" alt=""></p><ul><li>#fdisk    /dev/sdb   #开始分区</li></ul><p>n 创建新的分区-----分区类型 回车-----分区编号 回车----起始扇区 回车-----在last结束时 +分区容量</p><p>p 查看分区表</p><p>w 保存并退出</p><p><img src="'+d+'" alt=""></p><ul><li><h1 id="lsblk-或-用-fdisk-l-查看分区结果" tabindex="-1">lsblk 或 用 fdisk -l #查看分区结果 <a class="header-anchor" href="#lsblk-或-用-fdisk-l-查看分区结果" aria-label="Permalink to &quot;lsblk  或 用 fdisk -l   #查看分区结果&quot;">​</a></h1></li></ul><p><img src="'+r+'" alt=""></p><ul><li><p>parted /dev/设备文件</p></li><li><p>mklabel #创建一个分区表</p></li><li><p>gpt #我们要正确分区大于2TB的硬盘，应该使用gpt方式的分区表</p></li><li><p>yes #警告磁盘上的数据将会被销毁，询问是否继续，输入yes后回车</p></li><li><p>mkpart #进行分区操作, 分别输入分区名称、文件系统和分区的起止位置</p></li><li><p>print #打印输出分区信息</p></li></ul><p><img src="'+p+'" alt=""></p><ul><li><h1 id="mkfs-xfs-f-dev-sdb1-格式化文件系统xfs" tabindex="-1">mkfs.xfs -f /dev/sdb1 #格式化文件系统xfs <a class="header-anchor" href="#mkfs-xfs-f-dev-sdb1-格式化文件系统xfs" aria-label="Permalink to &quot;mkfs.xfs   -f   /dev/sdb1    #格式化文件系统xfs&quot;">​</a></h1></li></ul><p><img src="'+o+'" alt=""></p><ul><li><h1 id="blkid-dev-sdb1-查看文件系统类型和uuid" tabindex="-1">blkid /dev/sdb1 #查看文件系统类型和UUID <a class="header-anchor" href="#blkid-dev-sdb1-查看文件系统类型和uuid" aria-label="Permalink to &quot;blkid   /dev/sdb1      #查看文件系统类型和UUID&quot;">​</a></h1></li></ul><p><img src="'+n+'" alt="图片3"></p><ul><li><h1 id="mkdir-mypart-创建挂载点" tabindex="-1">mkdir /mypart #创建挂载点 <a class="header-anchor" href="#mkdir-mypart-创建挂载点" aria-label="Permalink to &quot;mkdir  /mypart  #创建挂载点&quot;">​</a></h1></li><li><h1 id="vim-etc-fstab-设置开机自动挂载" tabindex="-1">vim /etc/fstab #设置开机自动挂载 <a class="header-anchor" href="#vim-etc-fstab-设置开机自动挂载" aria-label="Permalink to &quot;vim    /etc/fstab   #设置开机自动挂载&quot;">​</a></h1></li></ul><p>UUID=[文件系统UUID] /mypart xfs defaults 0 0</p><p><img src="'+c+'" alt="图片4"></p><ul><li><h1 id="mount-a-刷新-重新加载-etc-fstab文件" tabindex="-1">mount -a # 刷新，重新加载/etc/fstab文件 <a class="header-anchor" href="#mount-a-刷新-重新加载-etc-fstab文件" aria-label="Permalink to &quot;mount   -a       # 刷新，重新加载/etc/fstab文件&quot;">​</a></h1></li></ul><p>检测/etc/fstab开机自动挂载配置文件,格式是否正确</p><p>检测/etc/fstab中,书写完成,但当前没有挂载的设备,进行挂载</p><ul><li><h1 id="df-h" tabindex="-1">df -h <a class="header-anchor" href="#df-h" aria-label="Permalink to &quot;df  -h&quot;">​</a></h1></li></ul><p><img src="'+b+'" alt="图片5"></p><p>执行reboot后，查看挂载点没有问题 就说明开机自动挂载生效了</p><p><strong>二</strong>**、**<strong>现有分区扩容</strong></p><p>这里我们以为/www扩容为例：</p><p>首先核实您的硬盘是否为LVM卷组，如果您的机器并不是LVM卷组，那您的硬盘就不支持扩容</p><ul><li><h1 id="lsblk-查看当前系统识别的硬盘-并记住当前容量" tabindex="-1">lsblk #查看当前系统识别的硬盘，并记住当前容量 <a class="header-anchor" href="#lsblk-查看当前系统识别的硬盘-并记住当前容量" aria-label="Permalink to &quot;lsblk  #查看当前系统识别的硬盘，并记住当前容量&quot;">​</a></h1></li></ul><p><img src="'+h+'" alt="图片1"></p><ul><li><h1 id="pvdisplay-查看卷组名称" tabindex="-1">pvdisplay #查看卷组名称 <a class="header-anchor" href="#pvdisplay-查看卷组名称" aria-label="Permalink to &quot;pvdisplay   #查看卷组名称&quot;">​</a></h1></li></ul><p><img src="'+f+'" alt="图片3"></p><ul><li>#parted /dev/sda print #显示当前磁盘分区，查看格式是否是GPT格式，并记住当前参数</li></ul><p><img src="'+u+'" alt="图片4"></p><p>如遇下截图中的报错：根据系统提示输入“Fix”，系统会自动将磁盘扩容部分的容量设置为GPT。</p><p><img src="'+m+'" alt="378061be-5fb1-4c27-9c01-14063d62badd"></p><p>mkpart primary 1075MB 250GB #第一个1075MB代表第二步里的End容量，第二个250GB代表Disk /dev/sdb容量</p><p>完成后quit退出</p><ul><li><h1 id="df-h-查看分区结果-这里我们可以看到已经分区成功。" tabindex="-1">df -h #查看分区结果，这里我们可以看到已经分区成功。 <a class="header-anchor" href="#df-h-查看分区结果-这里我们可以看到已经分区成功。" aria-label="Permalink to &quot;df -h        #查看分区结果，这里我们可以看到已经分区成功。&quot;">​</a></h1></li></ul><p><img src="'+g+'" alt="图片5"></p><p>将分区加入卷组</p><ul><li><h1 id="pvcreate-dev-sda2-将分区加入物理卷" tabindex="-1">pvcreate /dev/sda2 #将分区加入物理卷 <a class="header-anchor" href="#pvcreate-dev-sda2-将分区加入物理卷" aria-label="Permalink to &quot;pvcreate   /dev/sda2  #将分区加入物理卷&quot;">​</a></h1></li><li><h1 id="vgextend-vg-dev-sda2-扩展vg卷组" tabindex="-1">vgextend vg /dev/sda2 #扩展vg卷组 <a class="header-anchor" href="#vgextend-vg-dev-sda2-扩展vg卷组" aria-label="Permalink to &quot;vgextend   vg   /dev/sda2  #扩展vg卷组&quot;">​</a></h1></li><li><h1 id="lvextend-l-100-free-dev-vg-www-扩展逻辑卷" tabindex="-1">lvextend -l +100%free /dev/vg/www #扩展逻辑卷 <a class="header-anchor" href="#lvextend-l-100-free-dev-vg-www-扩展逻辑卷" aria-label="Permalink to &quot;lvextend  -l  +100%free  /dev/vg/www  #扩展逻辑卷&quot;">​</a></h1></li></ul><p>格式化文件系统</p><ul><li><h1 id="blkid-查看需扩容的分区文件系统" tabindex="-1">blkid #查看需扩容的分区文件系统 <a class="header-anchor" href="#blkid-查看需扩容的分区文件系统" aria-label="Permalink to &quot;blkid  #查看需扩容的分区文件系统&quot;">​</a></h1></li></ul><p><img src="'+v+'" alt="图片6"></p><p>xfs_growf命令是扩展xfs文件系统，resize2fs是扩展ext4文件系统</p><ul><li><p>#resize2fs /dev/vg/www #格式化为ext4</p></li><li><h1 id="df-h-这里我们可以看到已经扩容成功了" tabindex="-1">df -h #这里我们可以看到已经扩容成功了 <a class="header-anchor" href="#df-h-这里我们可以看到已经扩容成功了" aria-label="Permalink to &quot;df -h  #这里我们可以看到已经扩容成功了&quot;">​</a></h1></li></ul><p><img src="'+k+'" alt="图片7"></p><h2 id="reboot-最后重启进入系统再确认" tabindex="-1">reboot 最后重启进入系统再确认 <a class="header-anchor" href="#reboot-最后重启进入系统再确认" aria-label="Permalink to &quot;reboot  最后重启进入系统再确认&quot;">​</a></h2>',51)])])}const U=e(_,[["render",x]]);export{B as __pageData,U as default};
